Alla on yksinkertainen esimerkki C++-ohjelmasta, joka lukee tekstitiedoston rivi riviltä ja laskee tietyn sanan esiintymien määrän tiedostossa. Ohjelma käyttää standardikirjastoja ja ottaa tiedostonimen sekä etsittävän sanan komentoriviparametreina.

```cpp
#include <iostream>
#include <fstream>
#include <string>

int countWordInFile(const std::string& filename, const std::string& searchWord) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Ei voitu avata tiedostoa: " << filename << std::endl;
        return -1;
    }

    std::string word;
    int count = 0;

    while (file >> word) {
        if (word == searchWord) {
            count++;
        }
    }

    file.close();
    return count;
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::cerr << "Käyttö: " << argv[0] << " <tiedostonimi> <sana>" << std::endl;
        return 1;
    }

    std::string filename = argv[1];
    std::string searchWord = argv[2];

    int count = countWordInFile(filename, searchWord);
    if (count >= 0) {
        std::cout << "Sana '" << searchWord << "' esiintyy tiedostossa " << filename << " " << count << " kertaa." << std::endl;
    }

    return 0;
